from __future__ import annotations
import copy
STATES={'welcome': ['recent_projects', 'new_project', 'templates', 'empty', 'open_project', 'import_project'], 'code_editor': ['editing', 'split_editor', 'completion', 'inspection', 'rename_symbol', 'find_in_files'], 'layout_editor': ['design', 'blueprint', 'split', 'constraint_warning', 'attributes', 'add_component'], 'compose_preview': ['preview', 'multi_preview', 'interactive', 'render_error', 'refreshing', 'preview_config'], 'build': ['success', 'running', 'failed', 'tests', 'sync_required', 'build_options'], 'debugger': ['attached', 'paused', 'variables', 'breakpoints', 'disconnected', 'evaluate_expression'], 'logcat': ['streaming', 'paused', 'errors', 'no_device', 'filtered', 'save_filter'], 'device_manager': ['virtual_devices', 'running', 'physical', 'downloading', 'create_device', 'delete_device'], 'profiler': ['overview', 'cpu', 'memory', 'network', 'recording', 'capture_options'], 'sdk_manager': ['platforms', 'tools', 'updates', 'installing', 'license_dialog', 'apply_changes']}
POPUPS={'evaluate_expression', 'license_dialog', 'add_component', 'rename_symbol', 'capture_options', 'find_in_files', 'build_options', 'open_project', 'import_project', 'preview_config', 'save_filter', 'create_device', 'delete_device', 'apply_changes'}
NAV=[('welcome', 'home', 'Welcome'), ('code_editor', 'code', 'Editor'), ('layout_editor', 'dashboard', 'Layout'), ('compose_preview', 'preview', 'Compose'), ('build', 'build', 'Build'), ('debugger', 'bug_report', 'Debug'), ('logcat', 'list_alt', 'Logcat'), ('device_manager', 'devices', 'Devices'), ('profiler', 'speed', 'Profiler'), ('sdk_manager', 'settings', 'SDK')]
CODE='package com.example.trailnotes\n\nimport android.os.Bundle\nimport androidx.activity.ComponentActivity\nimport androidx.activity.compose.setContent\nimport androidx.compose.material3.*\n\nclass MainActivity : ComponentActivity() {\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        setContent {\n            TrailNotesTheme {\n                NotesScreen(notes = sampleNotes)\n            }\n        }\n    }\n}\n\n@Composable\nfun NotesScreen(notes: List<Note>) {\n    Scaffold(topBar = { Text("Trail Notes") }) { padding ->\n        LazyColumn(contentPadding = padding) {\n            items(notes) { note -> NoteCard(note) }\n        }\n    }\n}\n'
def generate_data(page,sample_index=0,assets_dir=None):
 if page not in STATES:raise ValueError(page)
 return {'page':page,'state':STATES[page][0],'popup_visible':False,'navigation':NAV,'project':'TrailNotes','code':CODE,'sample_index':sample_index,'files':[{'name':n,'icon':i,'change':c} for n,i,c in [('app','folder',''),('manifests','folder',''),('AndroidManifest.xml','description',''),('kotlin+java','folder',''),('MainActivity.kt','code','M'),('NotesScreen.kt','code','M'),('Note.kt','code',''),('res','folder',''),('activity_main.xml','description','M'),('Gradle Scripts','folder',''),('build.gradle.kts','build','')]],'devices':[{'name':n,'api':a,'resolution':r} for n,a,r in [('Pixel 8 API 35','35','1080 × 2400'),('Medium Phone API 34','34','1080 × 2400'),('Tablet API 35','35','2560 × 1600')]],'packages':[{'name':n,'version':v,'installed':i} for n,v,i in [('Android SDK Platform 35','35',True),('Android SDK Platform 34','34',True),('Android SDK Platform 33','33',False),('Android SDK Build-Tools','35.0.0',True),('Android SDK Platform-Tools','35.0.2',True),('Android Emulator','35.1.4',True),('Google USB Driver','13',False)]], 'logs':[{'time':f'10:24:{18+i}.240','level':l,'tag':t,'message':m} for i,(l,t,m) in enumerate([('I','ActivityTaskManager','Displayed MainActivity in 312 ms'),('D','NotesRepository','Loaded 12 notes from local cache'),('I','Choreographer','Frame rendered successfully'),('W','TrailNotes','Retrying request after timeout'),('E','AndroidRuntime','IllegalStateException: Missing note identifier'),('D','NotesRepository','Refresh completed')])]}
def apply_state(base,state):
 if state not in STATES[base['page']]:raise ValueError(state)
 d=copy.deepcopy(base);d['state']=state;d['popup_visible']=state in POPUPS
 if state=='errors':d['logs']=[x for x in d['logs'] if x['level']=='E']
 if state=='filtered':d['logs']=[x for x in d['logs'] if x['tag']=='NotesRepository']
 return d
